   194→async function downloadFile(url, outputPath) {
   195→  const controller = new AbortController();
   196→  const fiveMinMS = 5 * 60 * 1_000;
   197→  const timeoutId = setTimeout(() => controller.abort(), fiveMinMS);
   198→
   199→  try {
   200→    console.log(`Downloading: ${url}`);
   201→    const response = await fetch(url, { signal: controller.signal });
   202→
   203→    if (!response.ok) {
   204→      throw new Error(`HTTP ${response.status}`);
   205→    }
   206→
   207→    const file = fs.createWriteStream(outputPath);
   208→    await pipeline(Readable.fromWeb(response.body), file);
   209→
   210→    const fileSize = fs.statSync(outputPath).size;
   211→
   212→    if (fileSize === 0) {
   213→      fs.unlinkSync(outputPath);
   214→      throw new Error("Downloaded file is empty");
   215→    }
   216→  } catch (error) {
   217→    if (fs.existsSync(outputPath)) {
   218→      fs.unlinkSync(outputPath);
   219→    }
   220→
   221→    if (error.name === "AbortError") {
   222→      throw new Error(`Download timeout after 5m: ${url}`);
   223→    }
   224→    throw error;
   225→  } finally {
   226→    clearTimeout(timeoutId);
   227→  }
   228→}
