   234→  url.searchParams.set("platform", platform);
   235→  url.searchParams.set("dev", "false");
   236→  url.searchParams.set("hot", "false");
   237→  url.searchParams.set("lazy", "false");
   238→  url.searchParams.set("minify", "true");
