   260→    console.log(`Fetching ${platform} manifest...`);
   261→    const response = await fetch("http://localhost:8081/manifest", {
   262→      headers: { "expo-platform": platform },
   263→      signal: controller.signal,
   264→    });
   265→
   266→    if (!response.ok) {
   267→      throw new Error(`HTTP ${response.status}`);
   268→    }
   269→
   270→    const manifest = await response.json();
   271→    console.log(`${platform} manifest ready`);
   272→    return manifest;
   273→  } catch (error) {
   274→    if (error.name === "AbortError") {
   275→      throw new Error(
   276→        `Manifest download timeout after 5m for platform: ${platform}`,
   277→      );
   278→    }
   279→    throw error;
   280→  } finally {
   281→    clearTimeout(timeoutId);
   282→  }
