   285→async function downloadBundlesAndManifests(timestamp) {
   286→  console.log("Downloading bundles and manifests...");
   287→  console.log("This may take several minutes for production builds...");
   288→
   289→  try {
   290→    // Bundles are sequential — Metro can't handle both platforms simultaneously
   291→    // without stalling. Manifests are cheap and run in parallel after.
   292→    await downloadBundle("ios", timestamp);
   293→    await downloadBundle("android", timestamp);
   294→
   295→    const [iosManifest, androidManifest] = await Promise.all([
   296→      downloadManifest("ios"),
   297→      downloadManifest("android"),
