   307→function extractAssets(timestamp) {
   308→  const staticBuild = path.join(projectRoot, "static-build");
   309→  const bundles = {
   310→    ios: fs.readFileSync(
   311→      path.join(staticBuild, timestamp, "_expo", "static", "js", "ios", "bundle.js"),
   312→      "utf-8",
   313→    ),
   314→    android: fs.readFileSync(
   315→      path.join(staticBuild, timestamp, "_expo", "static", "js", "android", "bundle.js"),
   316→      "utf-8",
   317→    ),
   318→  };
   319→
   320→  const assetsMap = new Map();
   321→  const assetPattern =
   322→    /httpServerLocation:"([^"]+)"[^}]*hash:"([^"]+)"[^}]*name:"([^"]+)"[^}]*type:"([^"]+)"/g;
   323→
   324→  const extractFromBundle = (bundle, platform) => {
   325→    for (const match of bundle.matchAll(assetPattern)) {
   326→      const originalPath = match[1];
   327→      const filename = match[3] + "." + match[4];
   328→
   329→      const tempUrl = new URL(`http://localhost:8081${originalPath}`);
   330→      const unstablePath = tempUrl.searchParams.get("unstable_path");
   331→
   332→      if (!unstablePath) {
   333→        throw new Error(`Asset missing unstable_path: ${originalPath}`);
   334→      }
   335→
   336→      const decodedPath = decodeURIComponent(unstablePath);
   337→      const key = path.posix.join(decodedPath, filename);
   338→
   339→      if (!assetsMap.has(key)) {
   340→        const asset = {
   341→          url: path.posix.join("/", decodedPath, filename),
   342→          originalPath: originalPath,
   343→          filename: filename,
   344→          relativePath: decodedPath,
   345→          hash: match[2],
   346→          platforms: new Set(),
   347→        };
   348→
   349→        assetsMap.set(key, asset);
   350→      }
   351→      assetsMap.get(key).platforms.add(platform);
   352→    }
   353→  };
   354→
   355→  extractFromBundle(bundles.ios, "ios");
   356→  extractFromBundle(bundles.android, "android");
   357→
   358→  return Array.from(assetsMap.values());
   359→}
