   361→async function downloadAssets(assets, timestamp) {
   362→  if (assets.length === 0) {
   363→    return 0;
   364→  }
   365→
   366→  console.log("Copying assets...");
   367→  let successCount = 0;
   368→  const failures = [];
   369→
   370→  const downloadPromises = assets.map(async (asset) => {
   371→    const tempUrl = new URL(`http://localhost:8081${asset.originalPath}`);
   372→    const unstablePath = tempUrl.searchParams.get("unstable_path");
   373→
   374→    if (!unstablePath) {
   375→      throw new Error(`Asset missing unstable_path: ${asset.originalPath}`);
   376→    }
   377→
   378→    const decodedPath = decodeURIComponent(unstablePath);
   379→
   380→    const outputDir = path.join(
   381→      projectRoot,
   382→      "static-build",
   383→      timestamp,
   384→      "_expo",
   385→      "static",
   386→      "js",
   387→      asset.relativePath,
   388→    );
   389→    fs.mkdirSync(outputDir, { recursive: true });
   390→    const output = path.join(outputDir, asset.filename);
   391→
   392→    try {
   393→      const candidates = [
   394→        path.join(projectRoot, decodedPath, asset.filename),
   395→        path.join(workspaceRoot, decodedPath, asset.filename),
   396→      ];
   397→      const found = candidates.find((p) => fs.existsSync(p));
   398→      if (!found) {
   399→        throw new Error(`Asset not found on disk: ${asset.filename}`);
   400→      }
   401→      fs.copyFileSync(found, output);
   402→      successCount++;
   403→    } catch (error) {
   404→      failures.push({
   405→        filename: asset.filename,
   406→        error: error.message,
   407→        url: asset.originalPath,
   408→      });
   409→    }
   410→  });
   411→
   412→  await Promise.all(downloadPromises);
   413→
   414→  if (failures.length > 0) {
   415→    const errorMsg =
   416→      `Failed to download ${failures.length} asset(s):\n` +
   417→      failures
   418→        .map((f) => `  - ${f.filename}: ${f.error} (${f.url})`)
   419→        .join("\n");
   420→    exitWithError(errorMsg);
   421→  }
   422→
   423→  console.log(`Copied ${successCount} assets`);
   424→  return successCount;
   425→}
