   427→function updateBundleUrls(timestamp, baseUrl) {
   428→  const updateForPlatform = (platform) => {
   429→    const bundlePath = path.join(
   430→      projectRoot,
   431→      "static-build",
   432→      timestamp,
   433→      "_expo",
   434→      "static",
   435→      "js",
   436→      platform,
   437→      "bundle.js",
   438→    );
   439→    let bundle = fs.readFileSync(bundlePath, "utf-8");
   440→
   441→    bundle = bundle.replace(
   442→      /httpServerLocation:"(\/[^"]+)"/g,
   443→      (_match, capturedPath) => {
   444→        const tempUrl = new URL(`http://localhost:8081${capturedPath}`);
   445→        const unstablePath = tempUrl.searchParams.get("unstable_path");
   446→
   447→        if (!unstablePath) {
   448→          throw new Error(
   449→            `Asset missing unstable_path in bundle: ${capturedPath}`,
   450→          );
   451→        }
   452→
   453→        const decodedPath = decodeURIComponent(unstablePath);
   454→        return `httpServerLocation:"${baseUrl}${basePath}/${timestamp}/_expo/static/js/${decodedPath}"`;
   455→      },
   456→    );
   457→
   458→    fs.writeFileSync(bundlePath, bundle);
   459→  };
   460→
   461→  updateForPlatform("ios");
   462→  updateForPlatform("android");
   463→  console.log("Updated bundle URLs");
   464→}
