   466→function updateManifests(manifests, timestamp, baseUrl, assetsByHash) {
   467→  const updateForPlatform = (platform, manifest) => {
   468→    if (!manifest.launchAsset || !manifest.extra) {
   469→      exitWithError(`Malformed manifest for ${platform}`);
   470→    }
   471→
   472→    manifest.launchAsset.url = `${baseUrl}${basePath}/${timestamp}/_expo/static/js/${platform}/bundle.js`;
   473→    manifest.launchAsset.key = `bundle-${timestamp}`;
   474→    manifest.createdAt = new Date(
   475→      Number(timestamp.split("-")[0]),
   476→    ).toISOString();
   477→    manifest.extra.expoClient.hostUri =
   478→      baseUrl.replace("https://", "") + "/" + platform;
   479→    manifest.extra.expoGo.debuggerHost =
   480→      baseUrl.replace("https://", "") + "/" + platform;
   481→    manifest.extra.expoGo.packagerOpts.dev = false;
   482→
   483→    if (manifest.assets && manifest.assets.length > 0) {
   484→      manifest.assets.forEach((asset) => {
   485→        if (!asset.url) return;
   486→
   487→        const hash = asset.hash;
   488→        if (!hash) return;
   489→
   490→        const assetInfo = assetsByHash.get(hash);
   491→        if (!assetInfo) return;
   492→
   493→        asset.url = `${baseUrl}${basePath}/${timestamp}/_expo/static/js/${assetInfo.relativePath}/${assetInfo.filename}`;
   494→      });
   495→    }
   496→
   497→    fs.writeFileSync(
   498→      path.join(projectRoot, "static-build", platform, "manifest.json"),
   499→      JSON.stringify(manifest, null, 2),
   500→    );
   501→  };
   502→
   503→  updateForPlatform("ios", manifests.ios);
   504→  updateForPlatform("android", manifests.android);
   505→  console.log("Manifests updated");
   506→}
