    88→      if (!cell) { cell = []; g.set(key, cell); }
    89→      cell.push({ lat, lng, danger: flag === 1 });
    90→      _totalCount++;
    91→    }
    92→
    93→    console.log(`[seoulGIS] Grid built: ${_totalCount} crosswalks, ${g.size} cells`);
