     1→/**
     2→ * SignalContext.tsx — Seoul V2X Signal Provider (v3)
     3→ *
     4→ * WHAT CHANGED FROM v2:
     5→ *   - Reads nearestCrosswalkDist from GISContext (metres, null = not yet known)
     6→ *   - bestSignal is gated: only non-null when a crosswalk is ≤ PROXIMITY_THRESHOLD_M away
     7→ *   - Exposes crosswalkDist so SignalCard can display it
     8→ *
     9→ * POLLING:
    10→ *   Both phase + timing endpoints are fetched together every 5 seconds.
    11→ *   Polling pauses automatically when the app is backgrounded.
    12→ */
    13→
    14→import React, {
    15→  createContext,
    16→  useCallback,
    17→  useContext,
    18→  useEffect,
    19→  useRef,
    20→  useState,
    21→} from "react";
    22→import { AppState, AppStateStatus } from "react-native";
    23→
    24→import { getSignalData, type SignalTiming } from "@/services/signalAPI";
    25→import { useGIS } from "@/context/GISContext";
    26→
    27→// ─── Constants ────────────────────────────────────────────────────────────────
    28→
    29→const POLL_INTERVAL_MS       = 5_000;
    30→const PROXIMITY_THRESHOLD_M  = 50;
    31→
    32→// ─── Types ────────────────────────────────────────────────────────────────────
    33→
    34→interface SignalContextValue {
    35→  /** All active V2X signal readings (green-first sorted) */
    36→  signalTimings: SignalTiming[];
    37→  /**
    38→   * Best available signal — non-null only when the user is within
    39→   * PROXIMITY_THRESHOLD_M of a crosswalk (i.e. near an intersection).
    40→   */
    41→  bestSignal: SignalTiming | null;
    42→  /** Total number of active V2X stations returned by the API */
    43→  stationCount: number;
    44→  /** Distance in metres to the nearest crosswalk (null = not yet determined) */
    45→  crosswalkDist: number | null;
    46→  /** True while the very first fetch is in progress */
    47→  isLoadingSignal: boolean;
    48→  /** Last fetch error (null = OK) */
    49→  signalError: string | null;
    50→  /** Force an immediate out-of-cycle refresh */
    51→  refreshSignal: () => void;
    52→}
    53→
    54→const SignalContext = createContext<SignalContextValue | null>(null);
    55→
    56→// ─── Provider ─────────────────────────────────────────────────────────────────
    57→
    58→export function SignalProvider({ children }: { children: React.ReactNode }) {
    59→  const { nearestCrosswalkDist } = useGIS();
    60→
    61→  const [signalTimings,   setSignalTimings]   = useState<SignalTiming[]>([]);
    62→  const [rawBestSignal,   setRawBestSignal]   = useState<SignalTiming | null>(null);
    63→  const [stationCount,    setStationCount]    = useState(0);
    64→  const [isLoadingSignal, setIsLoadingSignal] = useState(true);
    65→  const [signalError,     setSignalError]     = useState<string | null>(null);
    66→
    67→  const isFetchingRef = useRef(false);
    68→  const timerRef      = useRef<ReturnType<typeof setInterval> | null>(null);
    69→
    70→  // ── Fetch ──────────────────────────────────────────────────────────────────
    71→  const fetchSignals = useCallback(async () => {
    72→    if (isFetchingRef.current) return;
    73→    isFetchingRef.current = true;
    74→
    75→    try {
    76→      const timings = await getSignalData();
    77→      setSignalTimings(timings);
    78→      setStationCount(timings.length);
    79→      setSignalError(null);
    80→      setRawBestSignal(timings.length > 0 ? timings[0] : null);
    81→    } catch {
    82→      setSignalError("V2X data unavailable");
    83→    } finally {
    84→      isFetchingRef.current = false;
    85→      setIsLoadingSignal(false);
    86→    }
    87→  }, []);
    88→
    89→  // ── Polling lifecycle ─────────────────────────────────────────────────────
    90→  const startPolling = useCallback(() => {
    91→    if (timerRef.current) return;
    92→    fetchSignals();
    93→    timerRef.current = setInterval(fetchSignals, POLL_INTERVAL_MS);
    94→  }, [fetchSignals]);
    95→
    96→  const stopPolling = useCallback(() => {
    97→    if (timerRef.current) {
    98→      clearInterval(timerRef.current);
    99→      timerRef.current = null;
   100→    }
   101→  }, []);
   102→
   103→  useEffect(() => {
   104→    startPolling();
   105→    return () => stopPolling();
   106→  }, [startPolling, stopPolling]);
   107→
   108→  // Pause when backgrounded
   109→  useEffect(() => {
   110→    const handler = (state: AppStateStatus) => {
   111→      state === "active" ? startPolling() : stopPolling();
   112→    };
   113→    const sub = AppState.addEventListener("change", handler);
   114→    return () => sub.remove();
   115→  }, [startPolling, stopPolling]);
   116→
   117→  const refreshSignal = useCallback(() => { fetchSignals(); }, [fetchSignals]);
   118→
   119→  // ── Proximity gate ────────────────────────────────────────────────────────
   120→  // Show the best signal only when a crosswalk is within 50 m.
   121→  // While GPS is still loading (null), we leave bestSignal null too.
   122→  const isNearby   = nearestCrosswalkDist !== null && nearestCrosswalkDist <= PROXIMITY_THRESHOLD_M;
   123→  const bestSignal = isNearby ? rawBestSignal : null;
   124→
   125→  return (
   126→    <SignalContext.Provider value={{
   127→      signalTimings,
   128→      bestSignal,
   129→      stationCount,
   130→      crosswalkDist: nearestCrosswalkDist,
   131→      isLoadingSignal,
   132→      signalError,
   133→      refreshSignal,
   134→    }}>
   135→      {children}
   136→    </SignalContext.Provider>
   137→  );
   138→}
   139→
   140→export function useSignal(): SignalContextValue {
   141→  const ctx = useContext(SignalContext);
   142→  if (!ctx) throw new Error("useSignal must be used within SignalProvider");
   143→  return ctx;
   144→}
