     1→/**
     2→ * GISContext.tsx — Geographic Information System (GIS) data provider
     3→ *
     4→ * PURPOSE (Research Schedule, Weeks 4–5):
     5→ *   Implements the "crosswalk entry detection module" described in the research plan.
     6→ *   - Watches the user's GPS location in real time
     7→ *   - Queries the OpenStreetMap Overpass API to find nearby crosswalks,
     8→ *     streetlights, and road types (no API key required — open data)
     9→ *   - Computes an "environment risk boost" (0–100) that the DetectionContext
    10→ *     uses to escalate alerts when the user is near a crosswalk or on a
    11→ *     busy road at night
    12→ *
    13→ * THREE-TRIGGER LOGIC (from research design spec):
    14→ *   Trigger 1: GPS within 30–350 m of a crosswalk  → crosswalk proximity boost
    15→ *   Trigger 2: Handled in DetectionContext (gyroscope pitch angle)
    16→ *   Trigger 3: No streetlights nearby               → darkness risk boost
    17→ *              Heavy/moderate traffic road type       → traffic risk boost
    18→ *              Steep slope from altitude change       → slope risk boost
    19→ *
    20→ * DATA SOURCE:
    21→ *   OpenStreetMap Overpass API (overpass-api.de + two fallback mirrors)
    22→ *   - No registration or API key needed
    23→ *   - Queries crosswalks within 350 m, streetlamps within 80 m,
    24→ *     road types within 80 m — all in a single batch request
    25→ */
    26→
    27→import React, {
    28→  createContext,
    29→  useCallback,
    30→  useContext,
    31→  useEffect,
    32→  useRef,
    33→  useState,
    34→} from "react";
    35→import { Platform } from "react-native";
    36→import * as Location from "expo-location";
    37→
    38→// ─── Types ────────────────────────────────────────────────────────────────────
    39→
    40→/** A simple lat/lng coordinate pair (used throughout the module) */
    41→export interface LatLng {
    42→  lat: number;
    43→  lng: number;
    44→}
    45→
    46→/**
    47→ * A crosswalk node returned by the Overpass API.
    48→ * id = OpenStreetMap node ID (unique identifier)
    49→ */
    50→export interface Crosswalk {
    51→  id: string;
    52→  lat: number;
    53→  lng: number;
    54→}
    55→
    56→/**
    57→ * Traffic level inferred from OSM road type tags.
    58→ * Maps to the "traffic volume API" in the research plan.
    59→ * Since we use open OSM data, we infer from road classification rather
    60→ * than live traffic counts.
    61→ */
    62→export type TrafficLevel = "none" | "light" | "moderate" | "heavy";
    63→
    64→/** Whether location permission has been granted, denied, or not yet asked */
    65→export type PermissionStatus = "unknown" | "granted" | "denied";
    66→
    67→/** All GIS state and actions exposed to child components via context */
    68→export interface GISState {
    69→  /** Current GPS position of the user (null until first fix) */
    70→  userLocation: (LatLng & { altitude: number | null; heading: number | null }) | null;
    71→  /** All crosswalk nodes found within 350 m */
    72→  nearbyCrosswalks: Crosswalk[];
    73→  /** Distance in metres to the nearest crosswalk (null = none found) */
    74→  nearestCrosswalkDist: number | null;
    75→  /** Number of streetlamp nodes found within 80 m */
    76→  streetlightCount: number;
    77→  /** Highest traffic level among all roads found within 80 m */
    78→  trafficLevel: TrafficLevel;
    79→  /** Terrain slope as a grade percentage (e.g. 8 = 8% grade) */
    80→  slope: number;
    81→  /** Combined environment risk score 0–100 fed into the detection engine */
    82→  gisRiskBoost: number;
    83→  permissionStatus: PermissionStatus;
    84→  isLoadingGIS: boolean;
    85→  gisError: string | null;
    86→  /** Ask the OS for foreground location permission */
    87→  requestPermission: () => Promise<void>;
    88→  /** Force a fresh Overpass query at the current position */
    89→  refreshGIS: () => void;
    90→}
    91→
    92→// ─── Helpers ──────────────────────────────────────────────────────────────────
    93→
    94→/** Earth radius in metres — used by the Haversine formula */
    95→const EARTH_R = 6_371_000;
    96→
    97→/**
    98→ * Haversine formula: great-circle distance between two lat/lng points.
    99→ * Used to:
   100→ *   1. Find the nearest crosswalk distance
   101→ *   2. Detect when the user has moved >100 m (triggers a new Overpass fetch)
   102→ *   3. Compute slope from consecutive GPS fixes
   103→ */
   104→function haversine(a: LatLng, b: LatLng): number {
   105→  const toRad = (d: number) => (d * Math.PI) / 180;
   106→  const dLat = toRad(b.lat - a.lat);
   107→  const dLng = toRad(b.lng - a.lng);
   108→  const sinLat = Math.sin(dLat / 2);
   109→  const sinLng = Math.sin(dLng / 2);
   110→  const h =
   111→    sinLat * sinLat +
   112→    Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * sinLng * sinLng;
   113→  return 2 * EARTH_R * Math.asin(Math.sqrt(h));
   114→}
   115→
   116→/**
   117→ * Maps an OSM highway tag to a traffic level.
   118→ * Motorways/primary roads → heavy; residential/service → light; footways → none.
   119→ * This is how we replicate "traffic volume API" data from the research plan
   120→ * using freely available OpenStreetMap tags.
   121→ */
   122→const TRAFFIC_MAP: Record<string, TrafficLevel> = {
   123→  motorway: "heavy",
   124→  motorway_link: "heavy",
   125→  trunk: "heavy",
   126→  trunk_link: "heavy",
   127→  primary: "heavy",
   128→  primary_link: "heavy",
   129→  secondary: "moderate",
   130→  secondary_link: "moderate",
   131→  tertiary: "moderate",
   132→  tertiary_link: "moderate",
   133→  unclassified: "light",
   134→  residential: "light",
   135→  living_street: "light",
   136→  service: "light",
   137→  pedestrian: "none",
   138→  footway: "none",
   139→  path: "none",
   140→  cycleway: "none",
   141→  steps: "none",
   142→};
   143→
   144→/** Numeric rank for comparison — used to pick the "worst" road within 80 m */
   145→function trafficRank(level: TrafficLevel): number {
   146→  return { none: 0, light: 1, moderate: 2, heavy: 3 }[level];
   147→}
   148→
   149→/**
   150→ * Overpass API mirrors — tried in order.
   151→ * overpass-api.de is the main server; the others are community mirrors.
   152→ * Having backups prevents the "GIS unavailable" error when the main
   153→ * server is slow (common from cloud IPs).
   154→ */
   155→const OVERPASS_MIRRORS = [
   156→  "https://overpass-api.de/api/interpreter",
   157→  "https://overpass.kumi.systems/api/interpreter",
   158→  "https://maps.mail.ru/osm/tools/overpass/api/interpreter",
   159→];
   160→
   161→/**
   162→ * queryOverpass — Fetches crosswalk, streetlight, and road data from OSM.
   163→ *
   164→ * Query breakdown:
   165→ *   node["highway"="crossing"](around:350,...) — crosswalks within 350 m
   166→ *   node["highway"="street_lamp"](around:80,...) — streetlights within 80 m
   167→ *   way["highway"](around:80,...)               — road segments within 80 m
   168→ *
   169→ * Uses `out body` (not `out body geom`) to keep response size small and
   170→ * avoid timeouts. Node elements include lat/lon; way elements include tags.
   171→ *
   172→ * Tries each mirror in sequence; throws only when all three fail.
   173→ */
   174→async function queryOverpass(
   175→  lat: number,
   176→  lng: number
   177→): Promise<{ crosswalks: Crosswalk[]; streetlightCount: number; trafficLevel: TrafficLevel }> {
   178→  const query = `
   179→[out:json][timeout:10];
   180→(
   181→  node["highway"="crossing"](around:350,${lat},${lng});
   182→  node["highway"="street_lamp"](around:80,${lat},${lng});
   183→  way["highway"](around:80,${lat},${lng});
   184→);
   185→out body;
   186→  `.trim();
   187→
   188→  let lastError: Error | null = null;
   189→
   190→  for (const mirror of OVERPASS_MIRRORS) {
   191→    try {
   192→      const res = await fetch(
   193→        mirror + "?data=" + encodeURIComponent(query),
   194→        { signal: AbortSignal.timeout(11_000) }  // 11s > query timeout=10s
   195→      );
   196→      if (!res.ok) throw new Error("HTTP " + res.status);
   197→      const json = await res.json();
   198→
   199→      const crosswalks: Crosswalk[] = [];
   200→      let streetlightCount = 0;
   201→      let bestTraffic: TrafficLevel = "none";
   202→
   203→      for (const el of json.elements ?? []) {
   204→        if (el.type === "node") {
   205→          const hw = el.tags?.["highway"];
   206→          if (hw === "crossing") {
   207→            // Each crossing node becomes a Crosswalk entry
   208→            crosswalks.push({ id: String(el.id), lat: el.lat, lng: el.lon });
   209→          } else if (hw === "street_lamp") {
   210→            streetlightCount += 1;  // Count lamps within 80 m
   211→          }
   212→        } else if (el.type === "way") {
   213→          const hw = el.tags?.["highway"] as string | undefined;
   214→          if (hw) {
   215→            // Keep only the "worst" (most dangerous) road type found nearby
   216→            const lvl = TRAFFIC_MAP[hw] ?? "light";
   217→            if (trafficRank(lvl) > trafficRank(bestTraffic)) bestTraffic = lvl;
   218→          }
   219→        }
   220→      }
   221→
   222→      return { crosswalks, streetlightCount, trafficLevel: bestTraffic };
   223→    } catch (e) {
   224→      lastError = e as Error;
   225→      // Try the next mirror
   226→    }
   227→  }
   228→
   229→  throw lastError ?? new Error("All Overpass mirrors failed");
   230→}
