   128→function haversine(a: LatLng, b: LatLng): number {
   129→  const toRad = (d: number) => (d * Math.PI) / 180;
   130→  const dLat = toRad(b.lat - a.lat);
   131→  const dLng = toRad(b.lng - a.lng);
   132→  const sinLat = Math.sin(dLat / 2);
   133→  const sinLng = Math.sin(dLng / 2);
   134→  const h =
   135→    sinLat * sinLat +
   136→    Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * sinLng * sinLng;
   137→  return 2 * EARTH_R * Math.asin(Math.sqrt(h));
