     1→/**
     2→ * seoulGIS.ts — Local crosswalk dataset for Seoul (서울특별시)
     3→ *
     4→ * SOURCE: 서울특별시 자치구별 신호등 및 횡단보도 위치 및 현황 (2023-05-30)
     5→ *   39,036 official crosswalk records, pre-converted to WGS84 and classified.
     6→ *
     7→ * FORMAT: { meta, data: [lat, lng, dangerFlag][] }
     8→ *   dangerFlag = 1  → 비신호 (uncontrolled) → "danger"
     9→ *   dangerFlag = 0  → 신호있음 (signalised)  → "caution"
    10→ *
    11→ * LAZY INIT: The spatial grid is built on first query call, not at module-load
    12→ * time. This avoids crashing the JS bundle if the JSON is slow to parse in
    13→ * the Hermes engine, and allows the rest of the app to load normally.
    14→ */
    15→
    16→import type { Crosswalk } from "@/context/GISContext";
    17→
    18→// ─── Seoul bounding box (with 2 km margin) ────────────────────────────────────
    19→const SEOUL_BOUNDS = {
    20→  latMin: 37.40,
    21→  latMax: 37.72,
    22→  lngMin: 126.72,
    23→  lngMax: 127.20,
    24→};
    25→
    26→/** Returns true when a GPS position is within Seoul metropolitan area */
    27→export function isInSeoul(lat: number, lng: number): boolean {
    28→  return (
    29→    lat >= SEOUL_BOUNDS.latMin &&
    30→    lat <= SEOUL_BOUNDS.latMax &&
    31→    lng >= SEOUL_BOUNDS.lngMin &&
    32→    lng <= SEOUL_BOUNDS.lngMax
    33→  );
    34→}
    35→
    36→// ─── Spatial grid (built lazily on first use) ─────────────────────────────────
    37→
    38→const GRID_DEG = 0.003;
    39→const EARTH_R  = 6_371_000;
    40→
    41→type GridEntry = { lat: number; lng: number; danger: boolean };
    42→type GridCell  = GridEntry[];
    43→
    44→let _grid: Map<string, GridCell> | null = null;
    45→let _totalCount = 0;
    46→let _loadError: string | null = null;
    47→
    48→function cellKey(lat: number, lng: number): string {
    49→  return `${Math.floor(lat / GRID_DEG)}_${Math.floor(lng / GRID_DEG)}`;
    50→}
    51→
    52→function haversineM(aLat: number, aLng: number, bLat: number, bLng: number): number {
    53→  const toRad = (d: number) => (d * Math.PI) / 180;
    54→  const dLat = toRad(bLat - aLat);
    55→  const dLng = toRad(bLng - aLng);
    56→  const s =
    57→    Math.sin(dLat / 2) ** 2 +
    58→    Math.cos(toRad(aLat)) * Math.cos(toRad(bLat)) * Math.sin(dLng / 2) ** 2;
    59→  return 2 * EARTH_R * Math.asin(Math.sqrt(s));
    60→}
    61→
    62→/**
    63→ * buildGrid — loads the Seoul crosswalk JSON and builds the spatial index.
    64→ * Called once on first query. Returns the grid (may be empty on failure).
    65→ */
    66→function buildGrid(): Map<string, GridCell> {
    67→  if (_grid !== null) return _grid;
    68→
    69→  const g = new Map<string, GridCell>();
    70→
    71→  try {
    72→    // eslint-disable-next-line @typescript-eslint/no-require-imports
    73→    const raw = require("../assets/seoul_crosswalks.json");
    74→
    75→    if (!raw || !Array.isArray(raw.data)) {
    76→      _loadError = `seoulGIS: invalid JSON shape (data=${typeof raw?.data})`;
    77→      console.error(_loadError);
    78→      _grid = g;
    79→      return g;
    80→    }
    81→
    82→    for (const row of raw.data) {
    83→      if (!Array.isArray(row) || row.length < 3) continue;
    84→      const [lat, lng, flag] = row as [number, number, number];
    85→      if (typeof lat !== "number" || typeof lng !== "number") continue;
    86→      const key = cellKey(lat, lng);
    87→      let cell = g.get(key);
    88→      if (!cell) { cell = []; g.set(key, cell); }
    89→      cell.push({ lat, lng, danger: flag === 1 });
    90→      _totalCount++;
    91→    }
    92→
    93→    console.log(`[seoulGIS] Grid built: ${_totalCount} crosswalks, ${g.size} cells`);
    94→  } catch (e) {
    95→    _loadError = `seoulGIS: failed to load JSON — ${String(e)}`;
    96→    console.error(_loadError);
    97→  }
    98→
    99→  _grid = g;
   100→  return g;
   101→}
   102→
   103→// ─── Public API ───────────────────────────────────────────────────────────────
   104→
   105→/**
   106→ * querySeoulCrosswalks
   107→ *
   108→ * Returns all official Seoul crosswalks within `radiusM` metres of (lat, lng).
   109→ * Builds the spatial grid on first call (lazy init).
   110→ *
   111→ * @param lat      WGS84 latitude of the query centre
   112→ * @param lng      WGS84 longitude of the query centre
   113→ * @param radiusM  Search radius in metres (default 350)
   114→ */
   115→export function querySeoulCrosswalks(
   116→  lat: number,
   117→  lng: number,
   118→  radiusM = 350
   119→): Crosswalk[] {
   120→  const grid = buildGrid();
   121→
   122→  if (grid.size === 0) {
   123→    console.warn("[seoulGIS] Grid is empty — returning no crosswalks");
   124→    return [];
   125→  }
   126→
   127→  const cellSpan =
   128→    Math.ceil(radiusM / (GRID_DEG * EARTH_R * (Math.PI / 180))) + 1;
   129→  const baseLat = Math.floor(lat / GRID_DEG);
   130→  const baseLng = Math.floor(lng / GRID_DEG);
   131→
   132→  const results: Crosswalk[] = [];
   133→
   134→  for (let dLat = -cellSpan; dLat <= cellSpan; dLat++) {
   135→    for (let dLng = -cellSpan; dLng <= cellSpan; dLng++) {
   136→      const key = `${baseLat + dLat}_${baseLng + dLng}`;
   137→      const cell = grid.get(key);
   138→      if (!cell) continue;
   139→      for (const entry of cell) {
   140→        if (haversineM(lat, lng, entry.lat, entry.lng) <= radiusM) {
   141→          results.push({
   142→            id: `seoul_${entry.lat.toFixed(6)}_${entry.lng.toFixed(6)}`,
   143→            lat: entry.lat,
   144→            lng: entry.lng,
   145→            riskLevel: entry.danger ? "danger" : "caution",
   146→          });
   147→        }
   148→      }
   149→    }
   150→  }
   151→
   152→  return results;
   153→}
   154→
   155→/**
   156→ * getSeoulGISStatus — returns a human-readable status string for debugging.
   157→ * Shown in the map view when crosswalk count is 0.
   158→ */
   159→export function getSeoulGISStatus(): string {
   160→  if (_grid === null) return "grid not built";
   161→  if (_grid.size === 0) return `grid empty${_loadError ? ": " + _loadError : ""}`;
   162→  return `${_totalCount} crosswalks, ${_grid.size} cells`;
   163→}
   164→
   165→/** Total number of crosswalks loaded into the grid */
   166→export const SEOUL_CROSSWALK_COUNT = {
   167→  get value() { return _totalCount; }
   168→};
