    33→const PHASE_URL  = `${BASE}/v2xSignalPhaseInformation/1.0?apikey=${SEOUL_API_KEY}`;
    34→const TIMING_URL = `${BASE}/v2xSignalPhaseTimingInformation/1.0?apikey=${SEOUL_API_KEY}`;
    35→
    36→// ─── Types ────────────────────────────────────────────────────────────────────
    37→
    38→export type SignalPhase = "red" | "green" | "unknown";
    39→
    40→export interface SignalTiming {
    41→  intersectionId: string;
    42→  phase:          SignalPhase;
    43→  remainingSec:   number;   // seconds remaining in current pedestrian phase
    44→  activeGreenDirs: string[]; // e.g. ["north","south"] — pedestrian green directions
