    51→  itstId?: string;
    52→  ntPdsgStatNm?: string | null;
    53→  etPdsgStatNm?: string | null;
    54→  stPdsgStatNm?: string | null;
    55→  wtPdsgStatNm?: string | null;
    56→  [key: string]: unknown;
    57→}
