    60→  itstId?: string;
    61→  ntPdsgRmdrCs?: number | null;
    62→  etPdsgRmdrCs?: number | null;
    63→  stPdsgRmdrCs?: number | null;
    64→  wtPdsgRmdrCs?: number | null;
    65→  [key: string]: unknown;
    66→}
    67→
    68→// ─── Helpers ──────────────────────────────────────────────────────────────────
    69→
    70→const DIR_LABELS: Record<string, string> = {
