    97→  const itstId      = phaseItem.itstId ?? "";
    98→
    99→  // Determine green directions and overall phase
   100→  const greenDirs: string[] = [];
   101→  let anyRed    = false;
   102→  let anyGreen  = false;
   103→
   104→  for (const key of PDSG_STAT_KEYS) {
   105→    const val = phaseItem[key];
   106→    const dir = key.slice(0, 2); // "nt", "et", "st", "wt"
   107→    if (isGreen(val)) { greenDirs.push(DIR_LABELS[dir] ?? dir); anyGreen = true; }
   108→    if (isRed(val))   { anyRed = true; }
