   115→  let remainingSec = 0;
   116→  if (timingItem) {
   117→    const rawVals = PDSG_TIME_KEYS
   118→      .map((k) => timingItem[k])
   119→      .filter((v): v is number => typeof v === "number" && v > 0);
   120→
   121→    if (rawVals.length > 0) {
   122→      // When GREEN: show longest remaining (most time to cross)
   123→      // When RED:   show shortest remaining (soonest green)
   124→      const raw = phase === "green"
   125→        ? Math.max(...rawVals)
   126→        : Math.min(...rawVals);
   127→      remainingSec = Math.round(raw / 10); // deciseconds → seconds
   128→    }
