   151→    const phaseItems: V2XPhaseItem[]   = await phaseRes.json();
   152→    const timingItems: V2XTimingItem[] = timingRes.ok ? await timingRes.json() : [];
   153→
   154→    // Build a timing lookup by itstId
   155→    const timingMap = new Map<string, V2XTimingItem>();
   156→    for (const t of timingItems) {
