   106→function haversineM(aLat: number, aLng: number, bLat: number, bLng: number): number {
   107→  const toRad = (d: number) => (d * Math.PI) / 180;
   108→  const dLat = toRad(bLat - aLat);
   109→  const dLng = toRad(bLng - aLng);
   110→  const s =
   111→    Math.sin(dLat / 2) ** 2 +
   112→    Math.cos(toRad(aLat)) * Math.cos(toRad(bLat)) * Math.sin(dLng / 2) ** 2;
   113→  return 2 * EARTH_R * Math.asin(Math.sqrt(s));
   114→}
