/**
 * seoulGIS.ts — Local crosswalk dataset for Seoul (서울특별시)
 *
 * SOURCE: 서울특별시 자치구별 신호등 및 횡단보도 위치 및 현황 (2023-05-30)
 *   39,036 official crosswalk records, pre-converted to WGS84 and classified.
 *
 * FORMAT: { meta, data: [lat, lng, dangerFlag][] }
 *   dangerFlag = 1  → 비신호 (uncontrolled) → "danger"
 *   dangerFlag = 0  → 신호있음 (signalised)  → "caution"
 *
 * LAZY INIT: The spatial grid is built on first query call, not at module-load
 * time. This avoids crashing the JS bundle if the JSON is slow to parse in
 * the Hermes engine, and allows the rest of the app to load normally.
 *
 * MISSING JSON: if `assets/seoul_crosswalks.json` is not bundled (e.g. file
 * not committed yet), the grid stays empty and `querySeoulCrosswalks` returns
 * []. GISContext detects this and silently falls back to the Overpass API.
 */

import type { Crosswalk } from "@/context/GISContext";

// ─── Seoul bounding box (with 2 km margin) ────────────────────────────────────
const SEOUL_BOUNDS = {
  latMin: 37.40,
  latMax: 37.72,
  lngMin: 126.72,
  lngMax: 127.20,
};

/** Returns true when a GPS position is within Seoul metropolitan area */
export function isInSeoul(lat: number, lng: number): boolean {
  return (
    lat >= SEOUL_BOUNDS.latMin &&
    lat <= SEOUL_BOUNDS.latMax &&
    lng >= SEOUL_BOUNDS.lngMin &&
    lng <= SEOUL_BOUNDS.lngMax
  );
}

// ─── Spatial grid (built lazily on first use) ─────────────────────────────────

const GRID_DEG = 0.003;
const EARTH_R  = 6_371_000;

type GridEntry = { lat: number; lng: number; danger: boolean };
type GridCell  = GridEntry[];

let _grid: Map<string, GridCell> | null = null;
let _totalCount = 0;
let _loadError: string | null = null;

function cellKey(lat: number, lng: number): string {
  return `${Math.floor(lat / GRID_DEG)}_${Math.floor(lng / GRID_DEG)}`;
}

function haversineM(aLat: number, aLng: number, bLat: number, bLng: number): number {
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(bLat - aLat);
  const dLng = toRad(bLng - aLng);
  const s =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(aLat)) * Math.cos(toRad(bLat)) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_R * Math.asin(Math.sqrt(s));
}

/**
 * buildGrid — loads the Seoul crosswalk JSON and builds the spatial index.
 * Called once on first query. Returns the grid (may be empty on failure).
 */
function buildGrid(): Map<string, GridCell> {
  if (_grid !== null) return _grid;

  const g = new Map<string, GridCell>();

  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const raw = require("../assets/seoul_crosswalks.json");

    if (!raw || !Array.isArray(raw.data)) {
      _loadError = `seoulGIS: invalid JSON shape (data=${typeof raw?.data})`;
      console.error(_loadError);
      _grid = g;
      return g;
    }

    for (const row of raw.data) {
      if (!Array.isArray(row) || row.length < 3) continue;
      const [lat, lng, flag] = row as [number, number, number];
      if (typeof lat !== "number" || typeof lng !== "number") continue;
      const key = cellKey(lat, lng);
      let cell = g.get(key);
      if (!cell) { cell = []; g.set(key, cell); }
      cell.push({ lat, lng, danger: flag === 1 });
      _totalCount++;
    }

    console.log(`[seoulGIS] Grid built: ${_totalCount} crosswalks, ${g.size} cells`);
  } catch (e) {
    _loadError = `seoulGIS: failed to load JSON — ${String(e)}`;
    console.warn(_loadError);
  }

  _grid = g;
  return g;
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * querySeoulCrosswalks
 *
 * Returns all official Seoul crosswalks within `radiusM` metres of (lat, lng).
 * Builds the spatial grid on first call (lazy init).
 */
export function querySeoulCrosswalks(
  lat: number,
  lng: number,
  radiusM = 350
): Crosswalk[] {
  const grid = buildGrid();

  if (grid.size === 0) {
    return [];
  }

  const cellSpan =
    Math.ceil(radiusM / (GRID_DEG * EARTH_R * (Math.PI / 180))) + 1;
  const baseLat = Math.floor(lat / GRID_DEG);
  const baseLng = Math.floor(lng / GRID_DEG);

  const results: Crosswalk[] = [];

  for (let dLat = -cellSpan; dLat <= cellSpan; dLat++) {
    for (let dLng = -cellSpan; dLng <= cellSpan; dLng++) {
      const key = `${baseLat + dLat}_${baseLng + dLng}`;
      const cell = grid.get(key);
      if (!cell) continue;
      for (const entry of cell) {
        if (haversineM(lat, lng, entry.lat, entry.lng) <= radiusM) {
          results.push({
            id: `seoul_${entry.lat.toFixed(6)}_${entry.lng.toFixed(6)}`,
            lat: entry.lat,
            lng: entry.lng,
            riskLevel: entry.danger ? "danger" : "caution",
          });
        }
      }
    }
  }

  return results;
}

/** Human-readable status for debugging */
export function getSeoulGISStatus(): string {
  if (_grid === null) return "grid not built";
  if (_grid.size === 0) return `grid empty${_loadError ? ": " + _loadError : ""}`;
  return `${_totalCount} crosswalks, ${_grid.size} cells`;
}

export const SEOUL_CROSSWALK_COUNT = {
  get value() { return _totalCount; },
};

/**
 * signalAPI.ts — Seoul V2X Real-time Traffic Signal Service
 *
 * TWO ENDPOINTS:
 *   1. v2xSignalPhaseInformation        — phase per direction/type (*StatNm)
 *   2. v2xSignalPhaseTimingInformation  — remaining time per dir/type (*RmdrCs ÷ 10 = sec)
 *
 * We only read the pedestrian (*Pdsg*) fields.
 */

const SEOUL_API_KEY =
  process.env.EXPO_PUBLIC_SEOUL_V2X_API_KEY ??
  "fc852b2e-4d4d-49c9-8b39-b806e977603f";

const BASE = "http://t-data.seoul.go.kr/apig/apiman-gateway/tapi";
const PHASE_URL  = `${BASE}/v2xSignalPhaseInformation/1.0?apikey=${SEOUL_API_KEY}`;
const TIMING_URL = `${BASE}/v2xSignalPhaseTimingInformation/1.0?apikey=${SEOUL_API_KEY}`;

// ─── Types ────────────────────────────────────────────────────────────────────

export type SignalPhase = "red" | "green" | "unknown";

export interface SignalTiming {
  intersectionId: string;
  phase:          SignalPhase;
  remainingSec:   number;
  activeGreenDirs: string[];
  timestamp:      number;
}

interface V2XPhaseItem {
  itstId?: string;
  ntPdsgStatNm?: string | null;
  etPdsgStatNm?: string | null;
  stPdsgStatNm?: string | null;
  wtPdsgStatNm?: string | null;
  [key: string]: unknown;
}

interface V2XTimingItem {
  itstId?: string;
  ntPdsgRmdrCs?: number | null;
  etPdsgRmdrCs?: number | null;
  stPdsgRmdrCs?: number | null;
  wtPdsgRmdrCs?: number | null;
  [key: string]: unknown;
}

const DIR_LABELS: Record<string, string> = {
  nt: "north", et: "east", st: "south", wt: "west",
};
const PDSG_STAT_KEYS = ["ntPdsgStatNm", "etPdsgStatNm", "stPdsgStatNm", "wtPdsgStatNm"] as const;
const PDSG_TIME_KEYS = ["ntPdsgRmdrCs", "etPdsgRmdrCs", "stPdsgRmdrCs", "wtPdsgRmdrCs"] as const;

function isGreen(v: string | null | undefined): boolean {
  return typeof v === "string" && v.toLowerCase().includes("allowed");
}
function isRed(v: string | null | undefined): boolean {
  return typeof v === "string" && v.toLowerCase().includes("stop");
}

function fetchWithTimeout(url: string, ms = 10_000): Promise<Response> {
  const ctrl = new AbortController();
  const tid  = setTimeout(() => ctrl.abort(), ms);
  return fetch(url, { signal: ctrl.signal }).finally(() => clearTimeout(tid));
}

function mergeRecord(
  phaseItem: V2XPhaseItem,
  timingItem: V2XTimingItem | undefined,
): SignalTiming {
  const now    = Date.now();
  const itstId = phaseItem.itstId ?? "";

  const greenDirs: string[] = [];
  let anyRed = false;
  let anyGreen = false;

  for (const key of PDSG_STAT_KEYS) {
    const val = phaseItem[key];
    const dir = key.slice(0, 2);
    if (isGreen(val)) { greenDirs.push(DIR_LABELS[dir] ?? dir); anyGreen = true; }
    if (isRed(val))   { anyRed = true; }
  }

  const phase: SignalPhase = anyGreen ? "green" : anyRed ? "red" : "unknown";

  let remainingSec = 0;
  if (timingItem) {
    const rawVals = PDSG_TIME_KEYS
      .map((k) => timingItem[k])
      .filter((v): v is number => typeof v === "number" && v > 0);
    if (rawVals.length > 0) {
      const raw = phase === "green" ? Math.max(...rawVals) : Math.min(...rawVals);
      remainingSec = Math.round(raw / 10);
    }
  }

  return { intersectionId: itstId, phase, remainingSec, activeGreenDirs: greenDirs, timestamp: now };
}

/**
 * getSignalData — fetches phase + timing and merges them.
 * Returns one SignalTiming per active V2X-equipped intersection in Seoul,
 * sorted green-first, then red, then unknown.
 */
export async function getSignalData(): Promise<SignalTiming[]> {
  try {
    const [phaseRes, timingRes] = await Promise.all([
      fetchWithTimeout(PHASE_URL),
      fetchWithTimeout(TIMING_URL),
    ]);

    if (!phaseRes.ok) throw new Error(`Phase API HTTP ${phaseRes.status}`);

    const phaseItems: V2XPhaseItem[]   = await phaseRes.json();
    const timingItems: V2XTimingItem[] = timingRes.ok ? await timingRes.json() : [];

    const timingMap = new Map<string, V2XTimingItem>();
    for (const t of timingItems) {
      if (t.itstId) timingMap.set(t.itstId, t);
    }

    const results = phaseItems.map((p) =>
      mergeRecord(p, p.itstId ? timingMap.get(p.itstId) : undefined)
    );

    return results.sort((a, b) => {
      const rank = { green: 0, red: 1, unknown: 2 } as const;
      return rank[a.phase] - rank[b.phase];
    });
  } catch (err) {
    console.warn("[signalAPI] getSignalData error:", err);
    return [];
  }
}

