const fs = await import('fs');
const raw = JSON.parse(fs.readFileSync('attached_assets/서울특별시_자치구_횡단보도_정보_1779632143249.json', 'utf-8'));
const rows = raw.DATA;
console.log('Total rows:', rows.length);

let bad = 0, low = 0, caution = 0, danger = 0;
const data = [];

for (const r of rows) {
  // Fields are swapped in the source: lot=lat value, lat=lng value
  const lat = parseFloat(r.lot);
  const lng = parseFloat(r.lat);
  if (!isFinite(lat) || !isFinite(lng) || lat < 37 || lat > 38 || lng < 126 || lng > 128) { bad++; continue; }

  const sgn  = r.sgn_yn === 'Y' ? 1 : 0;        // 보행등
  const pdsn = r.pdsn_sgn_yn === 'Y' ? 1 : 0;   // 보행자작동신호기
  const high = r.high_knd_yn === 'Y' ? 1 : 0;   // 고원식
  const flags = sgn | (pdsn << 1) | (high << 2);

  // Risk
  let risk;
  if (sgn && high)            risk = 0; // low
  else if (!sgn && !pdsn)     risk = 2; // danger
  else                        risk = 1; // caution
  if (high && risk === 2)     risk = 1; // raised bumps danger→caution

  if (risk === 0) low++;
  else if (risk === 1) caution++;
  else danger++;

  data.push([
    Math.round(lat * 1e6) / 1e6,
    Math.round(lng * 1e6) / 1e6,
    flags | (risk << 3),  // bits 0-2 = features, bits 3-4 = risk
  ]);
}

const out = {
  meta: {
    source: '서울특별시 자치구 횡단보도 정보',
    dataDate: rows[0]?.data_date ?? '2026-03-20',
    count: data.length,
    encoding: 'flags bitmask: bit0=sgn_yn, bit1=pdsn_sgn_yn, bit2=high_knd_yn, bits3-4=risk(0=low,1=caution,2=danger)',
  },
  data,
};
fs.writeFileSync('assets/seoul_crosswalks.json', JSON.stringify(out));
const stat = fs.statSync('assets/seoul_crosswalks.json');
console.log(`Wrote ${data.length} crosswalks (${bad} skipped), ${(stat.size/1024).toFixed(0)} KB`);
console.log(`Risk dist: low=${low}, caution=${caution}, danger=${danger}`);

