    // Legacy: dangerFlag=1 → danger, dangerFlag=0 → caution
    (encoded === 1 ? "danger" : "caution");

  const key = cellKey(lat, lng);
  let cell = g.get(key);
  if (!cell) { cell = []; g.set(key, cell); }
  cell.push({ lat, lng, risk, hasSignal, hasPedestrianButton, isRaised });
  _totalCount++;
}

