  nearestDist: number | null,
  lights: number,
  traffic: TrafficLevel,
  slopePct: number,
  dataLoaded: boolean
): number {
  let boost = 0;
  // Don't add boost until we have real data (avoid false alarms on startup)
  if (!dataLoaded) return 0;

  if (nearestDist !== null) {
    if (nearestDist < 15) boost += 35;
